def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    alive_count = len(alive)
    secure_supply = supply >= alive_count * WATER_REQ
    very_tight = supply < max(WATER_REQ, alive_count * WATER_REQ * 0.7)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    danger_prev = max(dangerous_prev) if dangerous_prev else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if day >= 8:
        urgency += 1

    if very_tight:
        urgency += 2
    elif not secure_supply:
        urgency += 1

    if secure_supply:
        base = 16.0
        if highest_prev > 0:
            base = min(base, max(10.0, avg_prev * 0.22))
    else:
        if highest_prev >= 180:
            base = 62.0 if urgency <= 2 else 96.0
        elif highest_prev >= 140:
            base = 54.0 if urgency <= 2 else 88.0
        elif highest_prev >= 90:
            base = highest_prev * 0.58 + 3.0
        elif highest_prev > 0:
            base = highest_prev + 2.5
        else:
            base = 42.0

    if urgency >= 6:
        base = max(base, danger_prev + 6.0, 98.0)
    elif urgency >= 4:
        base = max(base, danger_prev + 3.0, 72.0)
    elif urgency >= 2:
        base = max(base, min(68.0, avg_prev + 2.0 if avg_prev > 0 else 38.0))

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0:
        keep_reserve = reserve_days * 18.0
        if urgency <= 1:
            soft_cap = max(0.0, budget - keep_reserve)
        elif urgency == 2:
            soft_cap = max(0.0, budget - keep_reserve * 0.6)
        elif urgency == 3:
            soft_cap = max(0.0, budget - keep_reserve * 0.35)

    if soft_cap <= 0:
        soft_cap = min(budget, 22.0 if urgency <= 1 else 40.0)

    bid = min(base, soft_cap, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_prev + 8.0, 105.0))
    elif hp <= 4 or no_water_days >= 1:
        bid = min(budget, max(bid, highest_prev + 4.0, 78.0 if not secure_supply else 46.0))

    if secure_supply and urgency <= 1:
        bid = min(bid, 24.0)

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water = my_status['no_water_days']
    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Estimate opponent bids from yesterday
    prev_bids = []
    for o in alive_opponents.values():
        trace = o.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Danger threshold: if no water days or HP critical
    if my_hp <= 2 or no_water > 0:
        # Need water desperately, bid up to budget but not more than needed
        base_bid = min(my_budget, DAILY_SALARY * 0.9)
        if prev_bids:
            # Overbid highest previous by a small margin if affordable
            max_prev = max(prev_bids)
            return min(my_budget, max(base_bid, max_prev + 2.0))
        return base_bid

    # Normal situation: try to conserve
    if prev_bids:
        max_prev = max(prev_bids)
        # If supply is ample, bid low to save money
        if supply >= WATER_REQ * (1 + len(alive_opponents)):
            return min(my_budget, DAILY_SALARY * 0.3)
        else:
            # Need to compete; bid just above highest opponent to ensure win if possible
            target = max_prev + 1.5
            # Cap at budget
            return min(my_budget, target)
    else:
        # No history, base bid
        return min(my_budget, DAILY_SALARY * 0.5)
